#!/usr/bin/env bash
#
# mayhem/build.sh — builds the sanitized libFuzzer harnesses (+ -standalone reproducers) against libswoole,
# and the upstream gtest suite (core-tests) with the project's normal flags for mayhem/test.sh.
#
# Re-runnable and offline: everything comes from apt packages baked into the image; build dirs live under
# the gitignored /build, config.h and lib/ are gitignored generated files recreated on every run.
set -euo pipefail

[ -n "${SOURCE_DATE_EPOCH:-}" ] || unset SOURCE_DATE_EPOCH

: "${SANITIZER_FLAGS=-fsanitize=address,undefined -fno-sanitize-recover=all -fno-omit-frame-pointer}"
: "${DEBUG_FLAGS:=-g -gdwarf-3}"
: "${CC:=clang}" ; : "${CXX:=clang++}" ; : "${LIB_FUZZING_ENGINE:=-fsanitize=fuzzer}"
: "${MAYHEM_JOBS:=$(nproc)}"
: "${COVERAGE_FLAGS=}"
export SANITIZER_FLAGS DEBUG_FLAGS CC CXX LIB_FUZZING_ENGINE MAYHEM_JOBS COVERAGE_FLAGS

cd "$SRC"

# SanCov edge counters for the library objects (the sanitizer flags alone give none). Only when the fuzzer
# engine is in use and a sanitizer runtime is present to resolve the counter-registration hooks.
NOLINK=""
case "$LIB_FUZZING_ENGINE" in *fuzzer*) [ -z "$SANITIZER_FLAGS" ] || NOLINK="-fsanitize=fuzzer-no-link" ;; esac

# 0) config.h: the library's feature probes are generated by the PHP extension's autoconf step.
mkdir -p build
phpize >/dev/null
./configure --enable-sockets --enable-swoole-curl --enable-swoole-pgsql --enable-brotli --enable-zstd >build/configure.log 2>&1 \
  || { tail -50 build/configure.log; exit 1; }

# 1) libswoole with sanitizers + coverage, kept as a static archive of its objects.
cmake -S . -B build/fuzz -DCMAKE_BUILD_TYPE=Release \
  -DCMAKE_C_COMPILER="$CC" -DCMAKE_CXX_COMPILER="$CXX" \
  -DCMAKE_C_FLAGS="$SANITIZER_FLAGS $NOLINK $DEBUG_FLAGS" \
  -DCMAKE_CXX_FLAGS="$SANITIZER_FLAGS $NOLINK $DEBUG_FLAGS" \
  -DCMAKE_C_FLAGS_RELEASE="-O1" -DCMAKE_CXX_FLAGS_RELEASE="-O1" >/dev/null
cmake --build build/fuzz -j"$MAYHEM_JOBS" --target lib-swoole
rm -f build/libswoole_fuzz.a
find build/fuzz/CMakeFiles/lib-swoole.dir -name '*.o' | sort | xargs ar rcs build/libswoole_fuzz.a
# The sanitized shared library lands in lib/ (fixed output path); drop it so the test build relinks its own.
rm -f lib/libswoole.so*

# 2) Harnesses: fuzzer binary + standalone reproducer each, with leak detection turned off at build time.
INC="-I$SRC/include -I$SRC/include/wrapper -I$SRC/ext-src -I$SRC/thirdparty -I$SRC/thirdparty/llhttp -I$SRC -I$SRC/mayhem/harnesses -DHAVE_CONFIG_H"
LIBS="build/libswoole_fuzz.a -lpthread -ldl -lrt -lcrypt -luring -lssl -lcrypto -lbrotlienc -lbrotlidec -lz"
$CXX $SANITIZER_FLAGS $DEBUG_FLAGS -c mayhem/lsan_off.cc -o build/lsan_off.o
$CC $SANITIZER_FLAGS $DEBUG_FLAGS -c "$STANDALONE_FUZZ_MAIN" -o build/standalone_main.o
for h in fuzz_http_request fuzz_url_codec fuzz_multipart_parser fuzz_websocket fuzz_llhttp fuzz_redis_reply fuzz_redis_request fuzz_http2_mqtt; do
  $CXX -std=c++14 $SANITIZER_FLAGS $DEBUG_FLAGS -O1 $INC -c "mayhem/harnesses/$h.cc" -o "build/$h.o"
  $CXX $SANITIZER_FLAGS $DEBUG_FLAGS $LIB_FUZZING_ENGINE "build/$h.o" build/lsan_off.o $LIBS -o "$SRC/$h"
  $CXX $SANITIZER_FLAGS $DEBUG_FLAGS build/standalone_main.o "build/$h.o" build/lsan_off.o $LIBS -o "$SRC/$h-standalone"
done

# 3) Upstream gtest suite with NORMAL flags (independent build), run by mayhem/test.sh.
cmake -S . -B build/tests -DCMAKE_BUILD_TYPE=Release \
  -DCMAKE_C_COMPILER="$CC" -DCMAKE_CXX_COMPILER="$CXX" \
  -DCMAKE_C_FLAGS="$COVERAGE_FLAGS" -DCMAKE_CXX_FLAGS="$COVERAGE_FLAGS" >/dev/null
cmake --build build/tests -j"$MAYHEM_JOBS" --target core-tests
